CREATE TABLE IF NOT EXISTS staff_attendance (id BIGSERIAL PRIMARY KEY, staff_id BIGINT NOT NULL REFERENCES staff(id) ON DELETE CASCADE, date DATE NOT NULL, status TEXT NOT NULL DEFAULT 'present' CHECK (status IN ('present','absent','late','leave')), note TEXT NULL, recorded_by BIGINT NULL REFERENCES users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (staff_id, date));
CREATE TABLE IF NOT EXISTS leave_requests (id BIGSERIAL PRIMARY KEY, staff_id BIGINT NOT NULL REFERENCES staff(id) ON DELETE CASCADE, leave_type TEXT NOT NULL DEFAULT 'annual' CHECK (leave_type IN ('annual','sick','personal','unpaid')), start_date DATE NOT NULL, end_date DATE NOT NULL, reason TEXT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected')), approved_by BIGINT NULL REFERENCES users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK (end_date >= start_date));
CREATE TABLE IF NOT EXISTS payroll_runs (id BIGSERIAL PRIMARY KEY, staff_id BIGINT NOT NULL REFERENCES staff(id) ON DELETE CASCADE, period_label TEXT NOT NULL, base_cents BIGINT NOT NULL DEFAULT 0 CHECK (base_cents>=0), allowance_cents BIGINT NOT NULL DEFAULT 0 CHECK (allowance_cents>=0), deduction_cents BIGINT NOT NULL DEFAULT 0 CHECK (deduction_cents>=0), net_cents BIGINT NOT NULL DEFAULT 0 CHECK (net_cents>=0), paid_on DATE NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_staff_att_staff ON staff_attendance (staff_id, date);
CREATE INDEX IF NOT EXISTS idx_leave_staff ON leave_requests (staff_id, status);
CREATE INDEX IF NOT EXISTS idx_payroll_staff ON payroll_runs (staff_id, period_label);
